#!/usr/bin/env node

const path = require('path');
const fs = require('fs-extra');
const inquirer = require('inquirer');
const chalk = require('chalk');
const ora = require('ora');
const { execSync } = require('child_process');

const args = process.argv.slice(2);
const shouldInstall = args.includes('--install') || args.includes('-i');
const skipPromptsFlag = args.includes('--yes') || args.includes('-y');
const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';

const templatesDir = path.join(__dirname, '..', 'templates');

const log = {
  info: (msg) => console.log(chalk.blue(msg)),
  success: (msg) => console.log(chalk.green(msg)),
  error: (msg) => console.error(chalk.red(msg)),
};

const defaultAnswers = {
  projectName: 'my-app',
  framework: 'vanilla',
  styling: 'css',
  backend: false,
  description: 'Build fast. Learn faster.',
};

function getArgValue(flag) {
  const exactIndex = args.indexOf(flag);
  if (exactIndex !== -1) {
    const next = args[exactIndex + 1];
    if (next && !next.startsWith('-')) {
      return next;
    }
    return '';
  }

  const withEquals = args.find((arg) => arg.startsWith(`${flag}=`));
  if (withEquals) {
    return withEquals.split('=').slice(1).join('=').trim();
  }

  return null;
}

function parseCliFlags() {
  const name = getArgValue('--name');
  const framework = getArgValue('--framework');
  const styling = getArgValue('--styling');

  let backend = null;
  if (args.includes('--backend')) {
    const value = getArgValue('--backend');
    if (value === '' || value === null) {
      backend = true;
    } else {
      backend = value.toLowerCase() === 'true' || value === '1' || value === 'yes';
    }
  }
  if (args.includes('--no-backend')) {
    backend = false;
  }

  return {
    name,
    framework,
    styling,
    backend,
  };
}

function normalizeFramework(value) {
  if (!value) return null;
  const v = value.toLowerCase();
  if (v === 'react' || v === 'vanilla') return v;
  return null;
}

function normalizeStyling(value) {
  if (!value) return null;
  const v = value.toLowerCase();
  if (v === 'css') return 'css';
  if (v === 'tailwind' || v === 'tailwindcss') return 'tailwind';
  return null;
}

function validateProjectName(input) {
  const trimmed = input.trim();
  if (!trimmed) {
    return 'Project name cannot be empty.';
  }
  if (path.isAbsolute(trimmed)) {
    return 'Use a project name, not an absolute path.';
  }
  if (/[\\/]/.test(trimmed)) {
    return 'Project name cannot include path separators.';
  }
  if (trimmed === '.' || trimmed === '..') {
    return 'Project name cannot be "." or "..".';
  }
  return true;
}

function replaceInFile(filePath, searchValue, replaceValue) {
  const content = fs.readFileSync(filePath, 'utf8');
  const updated = content.split(searchValue).join(replaceValue);
  fs.writeFileSync(filePath, updated, 'utf8');
}

function replaceInFiles(filePaths, searchValue, replaceValue) {
  filePaths.forEach((filePath) => {
    if (fs.existsSync(filePath)) {
      replaceInFile(filePath, searchValue, replaceValue);
    }
  });
}

function updatePackageName(packagePath, name) {
  const pkg = fs.readJsonSync(packagePath);
  pkg.name = name;
  fs.writeJsonSync(packagePath, pkg, { spaces: 2 });
}

function generateReadme(targetDir, name, description) {
  const content = `# ${name}

${description}

Generated by weborbit 🚀

## Getting Started

npm install
npm run dev
`;
  fs.writeFileSync(path.join(targetDir, 'README.md'), content, 'utf8');
}

function installDependencies(targetDir, hasBackend) {
  execSync(`${npmCmd} install`, { cwd: targetDir, stdio: 'inherit' });

  if (hasBackend) {
    execSync(`${npmCmd} install`, { cwd: path.join(targetDir, 'server'), stdio: 'inherit' });
  }
}

function printNextSteps(name, shouldInstallNow, hasBackend) {
  console.log(`\n🎉 Project ready!\n\nNext steps:\ncd ${name}`);
  if (!shouldInstallNow) {
    console.log('npm install');
  }
  console.log('npm run dev');

  if (hasBackend) {
    console.log('\nBackend:');
    console.log('cd server');
    if (!shouldInstallNow) {
      console.log('npm install');
    }
    console.log('npm run dev');
  }
}

async function run() {
  console.log('weborbit');
  console.log('Create JS projects in seconds');
  console.log('');

  const cliFlags = parseCliFlags();
  const hasCliOverrides =
    skipPromptsFlag ||
    cliFlags.name !== null ||
    cliFlags.framework !== null ||
    cliFlags.styling !== null ||
    cliFlags.backend !== null;

  const cliFramework = normalizeFramework(cliFlags.framework);
  const cliStyling = normalizeStyling(cliFlags.styling);

  if (cliFlags.framework && !cliFramework) {
    log.error('Invalid --framework. Use "vanilla" or "react".');
    process.exit(1);
  }
  if (cliFlags.styling && !cliStyling) {
    log.error('Invalid --styling. Use "css" or "tailwind".');
    process.exit(1);
  }

  const answers = hasCliOverrides
    ? {
        projectName: (cliFlags.name || defaultAnswers.projectName).trim(),
        framework: cliFramework || defaultAnswers.framework,
        styling: cliStyling || defaultAnswers.styling,
        backend: cliFlags.backend !== null ? cliFlags.backend : defaultAnswers.backend,
        description: defaultAnswers.description,
      }
    : await inquirer.prompt([
        {
          name: 'projectName',
          type: 'input',
          message: 'Project name:',
          validate: validateProjectName,
          filter: (input) => input.trim(),
          default: defaultAnswers.projectName,
        },
        {
          name: 'description',
          type: 'input',
          message: 'Project description (optional):',
          default: defaultAnswers.description,
          filter: (input) => input.trim() || defaultAnswers.description,
        },
        {
          name: 'framework',
          type: 'list',
          message: 'Framework:',
          choices: [
            { name: 'Vanilla', value: 'vanilla' },
            { name: 'React (Vite)', value: 'react' },
          ],
          default: defaultAnswers.framework,
        },
        {
          name: 'styling',
          type: 'list',
          message: 'Styling:',
          choices: [
            { name: 'CSS only', value: 'css' },
            { name: 'Tailwind CSS', value: 'tailwind' },
          ],
          default: defaultAnswers.styling,
        },
        {
          name: 'backend',
          type: 'confirm',
          message: 'Include backend (Express)?',
          default: defaultAnswers.backend,
        },
      ]);

  const validationResult = validateProjectName(answers.projectName);
  if (validationResult !== true) {
    log.error(validationResult);
    process.exit(1);
  }

  const targetDir = path.resolve(process.cwd(), answers.projectName);

  if (fs.existsSync(targetDir)) {
    log.error(`Folder already exists: ${targetDir}`);
    process.exit(1);
  }

  const spinner = ora('Creating project...').start();

  try {
    fs.mkdirpSync(targetDir);

    const templateName =
      answers.styling === 'tailwind' ? `${answers.framework}-tailwind` : answers.framework;
    const frameworkTemplate = path.join(templatesDir, templateName);
    if (!fs.existsSync(frameworkTemplate)) {
      throw new Error(`Template not found: ${templateName}`);
    }
    fs.copySync(frameworkTemplate, targetDir);

    if (answers.backend) {
      const backendTemplate = path.join(templatesDir, 'backend', 'server');
      const backendTarget = path.join(targetDir, 'server');
      if (!fs.existsSync(backendTemplate)) {
        throw new Error('Backend template not found.');
      }
      fs.copySync(backendTemplate, backendTarget);
    }

    const rootPackagePath = path.join(targetDir, 'package.json');
    updatePackageName(rootPackagePath, answers.projectName);

    const htmlPath = path.join(targetDir, 'index.html');
    const reactAppPath = path.join(targetDir, 'src', 'App.jsx');
    replaceInFiles([htmlPath, reactAppPath], '__PROJECT_NAME__', answers.projectName);
    replaceInFiles([htmlPath, reactAppPath], '__PROJECT_DESCRIPTION__', answers.description);

    if (answers.backend) {
      const serverPackagePath = path.join(targetDir, 'server', 'package.json');
      if (fs.existsSync(serverPackagePath)) {
        updatePackageName(serverPackagePath, `${answers.projectName}-server`);
      }
    }

    generateReadme(targetDir, answers.projectName, answers.description);

    spinner.succeed('Project created.');

    if (shouldInstall) {
      log.info('Installing dependencies...');
      installDependencies(targetDir, answers.backend);
      log.success('Dependencies installed.');
    }

    printNextSteps(answers.projectName, shouldInstall, answers.backend);
  } catch (err) {
    spinner.fail('Project creation failed.');
    log.error(err.message || String(err));
    process.exit(1);
  }
}

run();
